                        scque_put1byte((byte)args[i]);
                    break;
                case ServerCommandArgsFormat.FMT_2x8byte:
                    for (int i = 0; i < 8; i++)
                        scque_put2byte((ushort)args[i]);
                    break;
                case ServerCommandArgsFormat.FMT_4x8byte:
                    for (int i = 0; i < 8; i++)
                        scque_put4byte((uint)args[i]);
                    break;
                case ServerCommandArgsFormat.FMT_1x9byte:
                    for (int i = 0; i < 9; i++)
                        scque_put1byte((byte)args[i]);
                    break;
                case ServerCommandArgsFormat.FMT_MSG:
                case ServerCommandArgsFormat.FMT_MSG_SE:
                    scque_put2byte((ushort)args[0]);
                    for (int i = 1; i < MSGARG_MAX_NUM; i++)
                        scque_put4byte((uint)args[i]);
                    break;
            }
        }
		private void read_core(global::Dpr.Battle.Logic.ServerCommandArgsFormat format, int[] args) {
            switch (format)
            {
                case ServerCommandArgsFormat.FMT_1byte:
                    args[0] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_2byte:
                    args[0] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_4byte:
                    args[0] = (int)scque_read4byte();
                    break;
                case ServerCommandArgsFormat.FMT_11byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_12byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_14byte:
                    args[0] = scque_read1byte();
                    args[1] = (int)scque_read4byte();
                    break;
                case ServerCommandArgsFormat.FMT_44bit:
                    unpack1_2args(scque_read1byte(), 4, 4, args, 0);
                    break;
                case ServerCommandArgsFormat.FMT_53bit:
                    unpack1_2args(scque_read1byte(), 5, 3, args, 0);
                    break;
                case ServerCommandArgsFormat.FMT_53bit_1byte:
                    unpack1_2args(scque_read1byte(), 5, 3, args, 0);
                    args[2] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_53bit_2byte:
                    unpack1_2args(scque_read1byte(), 5, 3, args, 0);
                    args[2] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_555bit:
                    unpack_3args(2, scque_read2byte(), 5, 5, 5, args, 0);
                    break;
                case ServerCommandArgsFormat.FMT_5_5_14bit:
                    unpack_3args(3, scque_read3byte(), 5, 5, 14, args, 0);
                    break;
                case ServerCommandArgsFormat.FMT_111byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read1byte();
                    args[2] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_112byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read1byte();
                    args[2] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_114byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read1byte();
                    args[2] = (int)scque_read4byte();
                    break;
                case ServerCommandArgsFormat.FMT_144byte:
                    args[0] = scque_read1byte();
                    args[1] = (int)scque_read4byte();
                    args[2] = (int)scque_read4byte();
                    break;
                case ServerCommandArgsFormat.FMT_53bit_12byte:
                    unpack1_2args(scque_read1byte(), 5, 3, args, 0);
                    args[2] = scque_read1byte();
                    args[3] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_5353bit:
                    unpack1_2args(scque_read1byte(), 5, 3, args, 0);
                    unpack1_2args(scque_read1byte(), 5, 3, args, 2);
                    break;
                case ServerCommandArgsFormat.FMT_5_5_14bit_1byte:
                    unpack_3args(3, scque_read3byte(), 5, 5, 14, args, 0);
                    args[3] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_5_5_14bit_2byte:
                    unpack_3args(3, scque_read3byte(), 5, 5, 14, args, 0);
                    args[3] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_5_5_6_2byte:
                    unpack_3args(2, scque_read2byte(), 5, 5, 6, args, 0);
                    args[3] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_1111byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read1byte();
                    args[2] = scque_read1byte();
                    args[3] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_1122byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read1byte();
                    args[2] = scque_read2byte();
                    args[3] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_1144byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read1byte();
                    args[2] = (int)scque_read4byte();
                    args[3] = (int)scque_read4byte();
                    break;
                case ServerCommandArgsFormat.FMT_555bit_22byte:
                    unpack_3args(2, scque_read2byte(), 5, 5, 5, args, 0);
                    args[3] = scque_read2byte();
                    args[4] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_5_3_7_1bit_2byte:
                    unpack_4args(2, scque_read2byte(), 5, 3, 7, 1, args, 0);
                    args[4] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_3311bit_2byte:
                    unpack_4args(1, scque_read1byte(), 3, 3, 1, 1, args, 0);
                    args[4] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_22222byte:
                    args[0] = scque_read2byte();
                    args[1] = scque_read2byte();
                    args[2] = scque_read2byte();
                    args[3] = scque_read2byte();
                    args[4] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_555555bit:
                    {
                        uint pack1 = scque_read2byte();
                        uint pack2 = scque_read2byte();
                        unpack_3args(2, pack1, 5, 5, 5, args, 0);
                        unpack_3args(2, pack2, 5, 5, 5, args, 3);
                        break;
                    }
                case ServerCommandArgsFormat.FMT_32111bit_2byte:
                    unpack_5args(1, scque_read1byte(), 3, 2, 1, 1, 1, args, 0);
                    args[5] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_5555bit_22byte:
                    unpack_4args(3, scque_read3byte(), 5, 5, 5, 5, args, 0);
                    args[4] = scque_read2byte();
                    args[5] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_556bit_222byte:
                    unpack_3args(2, scque_read2byte(), 5, 5, 6, args, 0);
                    args[3] = scque_read2byte();
                    args[4] = scque_read2byte();
                    args[5] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_111122byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read1byte();
                    args[2] = scque_read1byte();
                    args[3] = scque_read1byte();
                    args[4] = scque_read2byte();
                    args[5] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_5_5_14_7_1_8bit:
                    unpack_3args(3, scque_read3byte(), 5, 5, 14, args, 0);
                    unpack1_2args(scque_read1byte(), 7, 1, args, 3);
                    args[5] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_1x7byte:
                    for (int i = 0; i < 7; i++)
                        args[i] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_2x7byte:
                    for (int i = 0; i < 7; i++)
                        args[i] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_55511bit_22byte:
                    unpack_5args(3, scque_read3byte(), 5, 5, 5, 1, 1, args, 0);
                    args[5] = scque_read2byte();
                    args[6] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_55555bit_22byte:
                    unpack_5args(4, scque_read4byte(), 5, 5, 5, 5, 5, args, 0);
                    args[5] = scque_read2byte();
                    args[6] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_1111122byte:
                    args[0] = scque_read1byte();
                    args[1] = scque_read1byte();
                    args[2] = scque_read1byte();
                    args[3] = scque_read1byte();
                    args[4] = scque_read1byte();
                    args[5] = scque_read2byte();
                    args[6] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_1x8byte:
                    for (int i = 0; i < 8; i++)
                        args[i] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_2x8byte:
                    for (int i = 0; i < 8; i++)
                        args[i] = scque_read2byte();
                    break;
                case ServerCommandArgsFormat.FMT_4x8byte:
                    for (int i = 0; i < 8; i++)
                        args[i] = (int)scque_read4byte();
                    break;
                case ServerCommandArgsFormat.FMT_1x9byte:
                    for (int i = 0; i < 9; i++)
                        args[i] = scque_read1byte();
                    break;
                case ServerCommandArgsFormat.FMT_MSG:
                case ServerCommandArgsFormat.FMT_MSG_SE:
                    args[0] = scque_read2byte();
                    for (int i = 1; i < MSGARG_MAX_NUM; i++)
                        args[i] = (int)scque_read4byte();
                    break;
            }
        }
		private void scque_put1byte(byte data) {
            unsafe
            {
                m_buffer[m_writePtr++] = data;
            }
        }
		private void scque_put2byte(ushort data) {
            unsafe
            {
                m_buffer[m_writePtr++] = (byte)(data >> 8);
                m_buffer[m_writePtr++] = (byte)data;
            }
        }
		private void scque_put3byte(uint data) {
            unsafe
            {
                m_buffer[m_writePtr++] = (byte)(data >> 16);
                m_buffer[m_writePtr++] = (byte)(data >> 8);
                m_buffer[m_writePtr++] = (byte)data;
            }
        }
		private void scque_put4byte(uint data) {
            unsafe
            {
                m_buffer[m_writePtr++] = (byte)(data >> 24);
                m_buffer[m_writePtr++] = (byte)(data >> 16);
                m_buffer[m_writePtr++] = (byte)(data >> 8);
                m_buffer[m_writePtr++] = (byte)data;
            }
        }
		private byte scque_read1byte() {
            unsafe
            {
                return m_buffer[m_readPtr++];
            }
        }
		private ushort scque_read2byte() {
            unsafe
            {
                ushort data = (ushort)((m_buffer[m_readPtr] << 8) | m_buffer[(int)(m_readPtr + 1)]);
                m_readPtr += 2;
                return data;
            }
        }
		private uint scque_read3byte() {
            unsafe
            {
                uint data = (uint)((m_buffer[m_readPtr] << 16) | (m_buffer[(int)(m_readPtr + 1)] << 8) | m_buffer[(int)(m_readPtr + 2)]);
                m_readPtr += 3;
                return data;
            }
        }
		private uint scque_read4byte() {
            unsafe
            {
                uint data = (uint)((m_buffer[m_readPtr] << 24) | (m_buffer[(int)(m_readPtr + 1)] << 16) | (m_buffer[(int)(m_readPtr + 2)] << 8) | m_buffer[(int)(m_readPtr + 3)]);
                m_readPtr += 4;
                return data;
            }
        }
		private byte pack1_2args(int arg1, int arg2, int bits1, int bits2) {
            return (byte)(((byte)(arg1 & ~(-1 << bits1)) << bits2) | (arg2 & ~(-1 << bits2)));
        }
		private uint pack_3args(int bytes, int arg1, int arg2, int arg3, int bits1, int bits2, int bits3) {
            return (uint)(((ushort)(arg1 & ~(-1 << bits1)) << (bits2 + bits3))
                        | ((ushort)(arg2 & ~(-1 << bits2)) << bits3)
                        | (ushort)(arg3 & ~(-1 << bits3)));
        }
		private uint pack_4args(int bytes, int arg1, int arg2, int arg3, int arg4, int bits1, int bits2, int bits3, int bits4) {
            return (uint)(((ushort)(arg1 & ~(-1 << bits1)) << (bits2 + bits3 + bits4))
                        | ((ushort)(arg2 & ~(-1 << bits2)) << (bits3 + bits4))
                        | ((ushort)(arg3 & ~(-1 << bits3)) << bits4)
                        | (ushort)(arg4 & ~(-1 << bits4)));
        }
		private uint pack_5args(int bytes, int arg1, int arg2, int arg3, int arg4, int arg5, int bits1, int bits2, int bits3, int bits4, int bits5) {
            return (uint)(((ushort)(arg1 & ~(-1 << bits1)) << (bits2 + bits3 + bits4 + bits5))
                        | ((ushort)(arg2 & ~(-1 << bits2)) << (bits3 + bits4 + bits5))
                        | ((ushort)(arg3 & ~(-1 << bits3)) << (bits4 + bits5))
                        | ((ushort)(arg4 & ~(-1 << bits4)) << bits5)
                        | (ushort)(arg5 & ~(-1 << bits5)));
        }
		private void unpack1_2args(byte pack, int bits1, int bits2, int[] args, int idx_start) {
            args[idx_start] = (byte)((pack >> bits2) & ~(-1 << bits1));
            args[idx_start + 1] = pack & ~(-1 << bits2);
        }
		private void unpack_3args(int bytes, uint pack, int bits1, int bits2, int bits3, int[] args, int idx_start) {
            args[idx_start] = (ushort)((pack >> (bits2 + bits3)) & ~(uint)(-1 << bits1));
            args[idx_start + 1] = (ushort)((pack >> bits3) & ~(uint)(-1 << bits2));
            args[idx_start + 2] = (ushort)(pack & ~(uint)(-1 << bits3));
        }
		private void unpack_4args(int bytes, uint pack, int bits1, int bits2, int bits3, int bits4, int[] args, int idx_start) {
            args[idx_start] = (ushort)((pack >> (bits2 + bits3 + bits4)) & ~(uint)(-1 << bits1));
            args[idx_start + 1] = (ushort)((pack >> (bits3 + bits4)) & ~(uint)(-1 << bits2));
            args[idx_start + 2] = (ushort)((pack >> bits4) & ~(uint)(-1 << bits3));
            args[idx_start + 3] = (ushort)(pack & ~(uint)(-1 << bits4));
        }
		private void unpack_5args(int bytes, uint pack, int bits1, int bits2, int bits3, int bits4, int bits5, int[] args, int idx_start) {
            args[idx_start] = (ushort)((pack >> (bits2 + bits3 + bits4 + bits5)) & ~(uint)(-1 << bits1));
            args[idx_start + 1] = (ushort)((pack >> (bits3 + bits4 + bits5)) & ~(uint)(-1 << bits2));
            args[idx_start + 2] = (ushort)((pack >> (bits4 + bits5)) & ~(uint)(-1 << bits3));
            args[idx_start + 3] = (ushort)((pack >> bits5) & ~(uint)(-1 << bits4));
            args[idx_start + 4] = (ushort)(pack & ~(uint)(-1 << bits5));
        }
		private ushort _que_replace_ex_cmd(global::Dpr.Battle.Logic.ServerCommand reserveCmd, global::Dpr.Battle.Logic.ServerCommand replaceCmd, byte exVarCount) {
            ushort pos = (ushort)m_writePtr;
            byte reserveSize;
            if (exVarCount != 0)
            {
                reserveSize = (byte)(exVarCount + 3);
            }
            else
            {
                ServerCommandArgsFormat format = ServerCmdToFmtTbl[(int)reserveCmd];
                int[] args = new int[BattleServerConst.BTL_SERVERCMD_ARG_MAX];
                put_core(reserveCmd, format, args);
                reserveSize = (byte)(m_writePtr - pos);
            }

            m_writePtr = pos;
            scque_put2byte((ushort)replaceCmd);
            scque_put1byte((byte)(reserveSize - 3));
            m_writePtr = (uint)(pos + reserveSize);
            return pos;
        }
		public global::Dpr.Battle.Logic.ServerCommand scque_readcmd_support_skip(ref uint cmdReadState) {
            uint cmdPos = m_readPtr;
            ServerCommand cmd = (ServerCommand)scque_read2byte();
            while (cmd == ServerCommand._EX_RESERVE || cmd == ServerCommand._EX_SKIP)
            {
                byte skipSize = scque_read1byte();
                m_readPtr += skipSize;
                if (m_readPtr >= m_writePtr)
                    return ServerCommand.NUM;

                cmdPos = m_readPtr;
                cmd = (ServerCommand)scque_read2byte();
            }

            cmdReadState = cmdPos;
            return cmd;
        }
		static ServerCommandQueue() { }
	}
}
